/* Generated by scripts/postinstall.mjs (dev) / scripts/render-sw.mjs (build) — do not edit by hand. */
const CACHE_VERSION = '__CACHE_VERSION__';
const CONTENT_CACHE = `onyx-observer-content-${CACHE_VERSION}`;

/* The built app-shell URLs (hashed assets, document, manifest, icon),
 * stamped in by scripts/render-sw.mjs at build time. Empty in dev
 * (public/sw.js), where the runtime cache still learns everything after
 * the first visit; the production worker is install-time offline-first. */
const PRECACHE_URLS = [__PRECACHE_URLS__];

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CONTENT_CACHE);
      await Promise.allSettled(
        PRECACHE_URLS.map(async (url) => {
          const response = await fetch(url);
          if (response && response.ok) await cache.put(url, sanitizeForCache(response));
        }),
      );
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CONTENT_CACHE).map((key) => caches.delete(key))),
      )
      .then(() => self.clients.claim()),
  );
});

/* Static app-shell assets are hash-named by Vite, so a cache-first
 * strategy is safe there. Observer projections under /api are live data:
 * network-first, falling back to the last successful snapshot only when
 * offline — stale observer data shown with the offline banner is better
 * than nothing, but it must never win over fresh data. */
const apiRequest = (request) =>
  new URL(request.url).pathname.startsWith('/api/');

/* Responses from some hosts (incl. vite preview) carry `Vary: Origin`
 * plus permissive CORS headers. Storing them verbatim breaks Cache API
 * matching — `caches.match` honors Vary, so a later request without a
 * matching Origin never hits the entry. Strip the match-affecting and
 * CORS headers before caching; the body/encoding pass through unchanged. */
function sanitizeForCache(response) {
  const headers = new Headers(response.headers);
  headers.delete('vary');
  headers.delete('access-control-allow-origin');
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

async function networkFirst(request) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(CONTENT_CACHE);
      await cache.put(request, sanitizeForCache(response.clone()));
    }
    return response;
  } catch {
    return (await caches.match(request)) || Response.error();
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  return fetch(request);
}

/* Navigations get the app shell: network-first so a deploy's index.html
 * is picked up when online, falling back to the precached '/' when the
 * device is offline — the SPA keeps working with the installed shell. */
async function networkThenShell(request) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(CONTENT_CACHE);
      await cache.put(request, sanitizeForCache(response.clone()));
    }
    return response;
  } catch {
    return (
      (await caches.match('/')) ||
      (await caches.match('/index.html')) ||
      Response.error()
    );
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.mode === 'navigate') {
    event.respondWith(networkThenShell(request));
    return;
  }
  event.respondWith(apiRequest(request) ? networkFirst(request) : cacheFirst(request));
});

/* Phase 3.2: display and route notifications. */
self.addEventListener('push', (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = {};
  }
  const title = typeof payload.title === 'string' ? payload.title : 'ONYX Observer';
  const options = {
    body: typeof payload.message === 'string' ? payload.message : '',
    icon: '/icons/icon.svg',
    badge: '/icons/icon.svg',
    data: typeof payload.url === 'string' ? payload.url : '/notifications',
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    self.clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then(async (clients) => {
        const target = event.notification.data || '/';
        const client = clients.find((c) => 'focus' in c && 'navigate' in c);
        if (client) {
          try {
            await client.navigate(target);
            return client.focus();
          } catch {
            /* fall through to a fresh window */
          }
        }
        return self.clients.openWindow(target);
      }),
  );
});